// Gate: check if we have AI quota remaining
const quotaResult = $('Check AI Quota').first().json;
const used = parseInt(quotaResult.requests_made || 0);
const limit = parseInt(quotaResult.requests_limit || 50);

if (used >= limit) {
  console.log(`AI quota exhausted: ${used}/${limit} requests used today`);
  return [];
}

const remaining = limit - used;
const jobs = $('Fetch Unanalyzed Jobs').all();
const toProcess = jobs.slice(0, remaining);
console.log(`Processing ${toProcess.length} jobs (${remaining} quota remaining)`);
return toProcess;

// Parse AI response and handle errors gracefully
const apiResponse = $json;
const jobData = $('Build AI Prompt').item.json;

let analysis = null;
let parseError = null;

try {
  if (apiResponse.error) {
    throw new Error(`OpenRouter API error: ${JSON.stringify(apiResponse.error)}`);
  }

  const content = apiResponse.choices?.[0]?.message?.content || '';

  // Extract JSON from response (handle markdown code blocks and safety headers)
  let jsonStr = content;
  const codeBlockMatch = content.match(/```(?:json)?([\s\S]*?)```/);
  if (codeBlockMatch) jsonStr = codeBlockMatch[1];
  const startIdx = jsonStr.indexOf('{');
  const lastIdx = jsonStr.lastIndexOf('}');
  if (startIdx !== -1 && lastIdx !== -1 && lastIdx > startIdx) {
    jsonStr = jsonStr.substring(startIdx, lastIdx + 1);
  }

  analysis = JSON.parse(jsonStr);

  // Validate required fields
  const required = ['match_score', 'technical_score', 'experience_score'];
  for (const field of required) {
    if (analysis[field] === undefined) {
      analysis[field] = 0;
    }
    // Clamp scores to 0-100
    analysis[field] = Math.min(100, Math.max(0, Number(analysis[field]) || 0));
  }

} catch (e) {
  parseError = e.message;
  console.error(`Failed to parse AI response for job ${jobData.id}: ${e.message}`);

  // Default fallback analysis
  analysis = {
    match_score: 0,
    technical_score: 0,
    experience_score: 0,
    seniority_score: 0,
    language_score: 0,
    location_score: 0,
    visa_score: 0,
    strengths: [],
    missing_skills: [],
    risks: ['AI analysis failed - manual review required'],
    reasoning: `Parse error: ${parseError}`,
    should_apply: false
  };
}

return [{
  json: {
    job_id: jobData.id,
    company: jobData.company,
    title: jobData.title,
    url: jobData.url,
    location: jobData.location,
    remote: jobData.remote,
    ...analysis,
    parse_error: parseError,
    tokens_used: apiResponse.usage?.total_tokens || 0
  }
}];
